{"command":"python - <<'PY'
import json
p='/testbed/revocation_report.json'
with open(p) as f: d=json.load(f)
assert not any('_comment' in k for e in [d] for k in e)  # top-level quick check
assert len(d['employee_details']) == 10
privs=[p for e in d['employee_details'] for p in e['privileges']]
assert len(privs)==30
assert sum(p['privilege_revoked'] is True for p in privs)==29
assert sum(p['privilege_revoked'] is False for p in privs)==1
assert d['findings']['employees_notfully_revoked']==['emp_008']
def keys(x):
    if isinstance(x,dict):
        for k,v in x.items(): yield k; yield from keys(v)
    elif isinstance(x,list):
        for v in x: yield from keys(v)
assert not any(k.startswith('_comment') for k in keys(d))
print('Report validation passed: 10 employees, 30 privileges, 29 revoked, 1 active.')
PY","timeout":30}
